// Elf Tapestry: an endless tunnel whose walls are woven from a living
// ornament. The wall pattern is a Kali fractal (fold, invert, shift, again
// and again), which grows filigree, lace, eyes and scrollwork at every
// scale; its constant drifts along the journey, so the ornament never
// stops re-weaving itself. The tunnel is a log-polar map, so the flight
// inward is truly infinite, and every beat pulls you deeper.

#define TAU 6.28318531

mat2 rot(float a) {
  float c = cos(a);
  float s = sin(a);
  return mat2(c, -s, s, c);
}

vec3 palette(float t) {
  return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0) * 2.0;
  p = rot(j * 0.013) * p;

  float r = length(p) + 1e-4;
  // Two mirrored tiles per arm, so the pattern always closes around the wall.
  float n = 2.0 * float(arms);
  // Tunnel coordinates: x runs into the depth, y around the wall. Scaling
  // both by the same factor keeps the ornament undistorted.
  vec2 q = vec2(log(r), atan(p.y, p.x)) * n / TAU;
  q.y += q.x * spiral * 0.5;
  q.x -= j * 0.06;

  // Mirror-tile the wall, then hand each tile to the fractal.
  vec2 z = abs(fract(q * 0.5) * 2.0 - 1.0) - 0.5;
  z *= mix(0.45, 1.6, scale);
  z = rot(j * 0.011) * z;

  // The constant wanders; Form picks the neighbourhood it wanders in.
  float th = j * 0.017;
  vec2 c = mix(vec2(0.52, 0.62), vec2(0.95, 0.42), form) +
    0.14 * vec2(sin(th), cos(th * 1.37)) + 0.06 * vec2(sin(th * 2.9), cos(th * 2.3));

  float hue = colour + j * 0.011;
  float lineX = 1e3;
  float lineY = 1e3;
  float dot2 = 1e3;
  for (int i = 0; i < 6; i++) {
    // The clamp limits how hard a fold can magnify, which keeps the
    // ornament drawn in clean lines instead of dissolving into dust.
    z = abs(z) / clamp(dot(z, z), 0.22, 6.0) - c;
    lineX = min(lineX, abs(z.x));
    lineY = min(lineY, abs(z.y));
    dot2 = min(dot2, dot(z, z));
  }

  // Stained glass between the threads, coloured by how the orbit settled.
  vec3 col = palette(hue + 0.45 * log(dot2 + 0.03) + 0.6 * lineX);
  col = mix(col, col * col * 1.3, 0.8);
  // Leading between the panes, along the fold lines.
  col *= 0.04 + 0.96 * smoothstep(0.0, 0.16, lineX) * smoothstep(0.0, 0.12, lineY);
  // Gold filigree inside the leading, jewels where the orbit comes home.
  col += vec3(1.0, 0.75, 0.35) * 0.8 * exp(-70.0 * lineX);
  col += palette(hue + 0.5) * 0.6 * exp(-70.0 * lineY);
  col += palette(hue + 0.3 + sqrt(dot2)) * 1.2 * exp(-40.0 * dot2);
  col *= mix(0.6, 1.9, glow);

  // Depth: the wall dims into the distance and a light burns at the end.
  float depth = smoothstep(0.0, 0.45, r);
  col *= 0.15 + 0.85 * depth;
  // Near the vanishing point the ornament is finer than a pixel.
  float fine = smoothstep(2.0, 9.0, n / TAU / r * 2.0 / resolution.y * 60.0);
  col = mix(col, palette(hue + 0.6) * 0.25, fine);
  col += (palette(hue + 0.15) + 0.4) * 0.018 / (r * r + 0.012);

  col = 1.0 - exp(-col * 1.1);
  return clamp(col, 0.0, 1.0);
}
